async function _mmChkNet(v, group) {
const hosts = _mmHostList(v, group);
const tried = [];
let okHost = '';
const voices = [];
for (const h of hosts) {
const label = String(h.host).replace(/^https?:\/\//, '');
const got = [];
let why = '';
for (const ty of ['system', 'voice_cloning']) {
try {
_mmVoiceEntries(await _mmFetchJSON(h, v, group, '/v1/get_voice', { voice_type: ty }))
.forEach(x => { if (!got.some(y => y.id === x.id)) got.push(x); });
} catch (e) { if (!why) why = _mmWhy(e); }
}
if (got.length) {
okHost = h.host;
got.forEach(x => voices.push(x));
tried.push('✓ ' + label + '：连上了，Key 被这本账户承认（这一本下 ' + got.length + ' 个音色）');
break;
}
tried.push('✗ ' + label + '：' + (why || '连上了但没回话'));
}
return { okHost, voices, tried };
}
async function _mmChkModelList(v, group, host) {
const cand = { host, legacy: /minimax(i)?\.chat/i.test(host) };
let ids = [];
for (const p of ['/v1/models', '/v1/model/list']) {
try {
const got = _mmModelIds(await _mmFetchJSON(cand, v, group, p));
if (got.length) return { answered: true, ids: got };
} catch (e) {   }
}
return { answered: true, ids };
}
